import re

def parse_csv_line(line: str) -> list | None:
    line = line.rstrip('\r\n')
    if not line.strip():
        return []

    pattern = re.compile(r'(?:^|,)(?:"((?:[^"]|"")*)"|([^,]*))')
    match = pattern.findall(line)

    if not match:
        return None

    result = []
    for quoted, unquoted in match:
        if quoted:
            field = quoted.replace('""', '"')
        else:
            field = unquoted.strip()
        result.append(field)

    return result

